    async def get_pipeline_runs(
        self,
        limit: Union[Optional[int], UnsetType] = UNSET,
        offset: Union[Optional[int], UnsetType] = UNSET,
        where: Union[Optional[pipeline_runs_bool_exp], UnsetType] = UNSET,
        **kwargs: Any,
    ) -> GetPipelineRuns:
        query = gql("""
            query GetPipelineRuns($limit: Int = 12, $offset: Int = 0, $where: pipeline_runs_bool_exp = {}) {
              pipeline_runs(
                order_by: {created_at: desc}
                limit: $limit
                offset: $offset
                where: $where
              ) {
                id
                pipeline {
                  name
                  slug
                  output_schema
                  input_schema
                  ui_schema
                  cancellable
                }
                status
                input
                output
                error_message
                credits_charged
                created_at
                completed_at
                workflow_execution {
                  status
                  start_time
                  close_time
                }
              }
              pipeline_runs_aggregate(where: $where) {
                aggregate {
                  count
                }
              }
              completed: pipeline_runs_aggregate(
                where: {_and: [$where, {status: {_eq: "completed"}}]}
              ) {
                aggregate {
                  count
                  sum {
                    credits_charged
                  }
                }
              }
            }
            """)
        variables: dict[str, object] = {
            "limit": limit,
            "offset": offset,
            "where": where,
        }
        response = await self.execute(
            query=query, operation_name="GetPipelineRuns", variables=variables, **kwargs
        )
        data = self.get_data(response)
        return GetPipelineRuns.model_validate(data)

